const items = $input.all();
const records = items.map(i => i.json);

if (!records || records.length === 0) {
  return [{
    json: {
      error: "ไม่มีข้อมูลผลสอบในตาราง exam_results กรุณาทำข้อสอบผ่านแบบฟอร์มก่อน"
    }
  }];
}

const totalStudents = records.length;
const totalScores = records.reduce((sum, r) => sum + Number(r.score), 0);
const avgScore = (totalScores / totalStudents).toFixed(2);
const maxScore = Math.max(...records.map(r => Number(r.score)));
const minScore = Math.min(...records.map(r => Number(r.score)));
const passCount = records.filter(r => r.pass_status === 'ผ่าน').length;
const failCount = totalStudents - passCount;
const passRate = ((passCount / totalStudents) * 100).toFixed(1);

return [{
  json: {
    summary: {
      subject: records[0].subject || 'วิทยาศาสตร์',
      test_name: records[0].test_name || 'แบบทดสอบบทที่ 1',
      total_students: totalStudents,
      avg_score: avgScore,
      max_score: maxScore,
      min_score: minScore,
      pass_count: passCount,
      fail_count: failCount,
      pass_rate: `${passRate}%`
    },
    students_data: records,
    formatted_data_string: JSON.stringify(records, null, 2)
  }
}];
